import { Recycling, RestartAlt } from '@mui/icons-material';
import React, { useEffect, useState } from 'react';
import { translateProperty } from './jds/components/PlanteInfo';
import {
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Button,
  Typography,
  Box,
  Stack,
  Slide,
  IconButton,
  Divider,
  Popover
} from "@mui/material";
import EmojiEventsIcon from "@mui/icons-material/EmojiEvents";
import ReplayIcon from "@mui/icons-material/Replay";
import CloseIcon from "@mui/icons-material/Close";
import { useGlobalScores } from './App';

const ChuckNorrisFact = ()=> {
  const [fact, setFact] = useState('');
  const [en_fact, setENFact] = useState('');
  const [trlstd, setTranslated] = useState(false);

  useEffect(()=>{
    handleFetchFact();
  },[]);



  useEffect(() => {
    const translateFact = async () => {
        if(en_fact!==''){
            const translation = await translateProperty(en_fact);
            setFact(translation);
            setTranslated(true);

        }
    };
    if(!trlstd)
        translateFact();
  }, [en_fact,trlstd]);

  const handleFetchFact = () => {
    setTranslated(false);
    fetch('https://api.chucknorris.io/jokes/random')
      .then((response) => response.json())
      .then((data) => {
        setENFact(data.value);
      })
      .catch((error) => {
        console.error('Error fetching Chuck Norris fact:', error);
        setFact('Erreur lors de la récupération du Chuck Norris fact.');
      });
  };
  
  return (
    <Box style={{justifyContent:'center',alignItems:'center',padding:'20px',display:'flex'}}>
        <Box style={{flexDirection:'column', display:'flex'}}>

        <Typography style={{textAlign:'center',fontSize: '24px',  textShadow: '2px 2px 10px rgba(0, 0, 0, 0.3)'}}>{fact}</Typography>
    <Typography style={{textAlign:'center',fontSize: '14px',  textShadow: '2px 2px 10px rgba(100, 100, 100, 0.3)'}}>{en_fact}</Typography>
        </Box>
    <IconButton onClick={handleFetchFact}><RestartAlt/></IconButton>
    </Box>
  );
}

export default ChuckNorrisFact;



export const GameOver = ({ open = false, gameName, score, gameOverReason, handleClose, handleRestart}) => {
  const { setScore, getScoreByGame } = useGlobalScores();
  const [hiScore, setHiScore] = useState("Aucun");
  const [isNewRecord, setIsNewRecord] = useState(false);

  const doClose = (evt, reason) => {
    if (reason !== "backdropClick") handleClose(evt);
  };

  const doRestart = (evt) => {
    handleRestart();
    handleClose(evt);
  };

  useEffect(() => {
    if (gameName != null) {
      const hiscores = getScoreByGame(gameName);
      if (hiscores != null && hiscores.score != null) {
        setHiScore(hiscores.score);
        if (score > hiscores.score) {
          setScore(gameName, score);
          setIsNewRecord(true);
        }
      } else {
        setHiScore("Aucun");
        setScore(gameName, score);
        setIsNewRecord(true);
      }
    }
  }, [gameName, score]);

  return (
    <Dialog
      open={open}
      onClose={doClose}
      maxWidth="xs"
      fullWidth
      TransitionComponent={Slide}
      TransitionProps={{ direction: "up" }}
      PaperProps={{
        sx: {
          background: "#1c1c1cff",
          border: "2px solid gold",
          color: "white",
          fontFamily: '"Press Start 2P", monospace',
          textAlign: "center"
        }
      }}
    >
      <DialogTitle sx={{ fontSize: 16, color: "#FFD700" }}>
        🎮 Partie terminée
      </DialogTitle>

      <DialogContent>
        <Stack spacing={2} alignItems="center">
          <Box sx={{ display: "flex", gap:3, alignItems: "center" }}>
            {gameOverReason&&<Typography variant="h6" sx={{ color: "#e3cfaaff" }}>
              {gameOverReason}
            </Typography>}
          <Typography variant="h6" sx={{ color: "white" }}>
            Votre score :
          </Typography>
          <Typography variant="h4" sx={{ color: "#00FF88" }}>
            {score}
          </Typography>
          </Box>

          {isNewRecord && (
            <Box
              sx={{
                background: "#222",
                border: "1px solid gold",
                px: 2,
                py: 1,
                borderRadius: 2,
                animation: "pulse 1s infinite alternate"
              }}
            >
              <EmojiEventsIcon sx={{ color: "gold", mr: 1 }} />
              <Typography sx={{ color: "#FFD700", fontWeight: "bold" }}>
                Nouveau record !
              </Typography>
            </Box>
          )}

          {!isNewRecord && (
            <Typography variant="body2" sx={{ color: "#aaa" }}>
              🏆 Hi-score actuel :{" "}
              <strong style={{ color: "#ffdd55" }}>{hiScore}</strong>
            </Typography>
          )}
        </Stack>
      </DialogContent>

      <DialogActions sx={{ justifyContent: "center", pb: 2 }}>
        <Button
          onClick={handleClose}
          startIcon={<CloseIcon />}
          variant="outlined"
          sx={{ borderColor: "#555", color: "#ccc" }}
        >
          Fermer
        </Button>
        {typeof handleRestart=='function' &&<Button
          onClick={doRestart}
          startIcon={<ReplayIcon />}
          variant="contained"
          sx={{
            backgroundColor: "#FFD700",
            color: "#111",
            fontWeight: "bold",
            "&:hover": {
              backgroundColor: "#ffc107"
            }
          }}
        >
          Recommencer
        </Button>}
      </DialogActions>

      {/* Animations globals */}
      <style>
        {`
        @keyframes pulse {
          0% { transform: scale(1); opacity: 1; }
          100% { transform: scale(1.05); opacity: 0.8; }
        }
      `}
      </style>
    </Dialog>
  );
};

export const HiScoreButton = () => {
  const { allScores } = useGlobalScores();
  const [anchorEl, setAnchorEl] = useState(null);

  const handleOpen = (event) => {
    setAnchorEl(event.currentTarget);
  };
  const handleClose = () => setAnchorEl(null);

  const open = Boolean(anchorEl);
  const id = open ? "hiscore-popover" : undefined;

  // Récupération brute des scores
  // const allRawScores = allScores; // ou reparse directement localStorage
  // const scoreData = Object.entries(
  //   JSON.parse(localStorage.getItem("globalScores") || "{}")
  // );

  const sortedScores = allScores==null?[]:Object.entries(allScores)
    .filter(([id, data]) => data?.score)
    .sort((a, b) => b[1].score - a[1].score);

  return (
    <>
      <IconButton
        onClick={handleOpen}
        color="primary"
        aria-describedby={id}
        size="large"
        sx={{
          position: "absolute",
          top: 16,
          right: 16,
          backgroundColor: "#ffe082",
          "&:hover": { backgroundColor: "#ffca28" }
        }}
      >
        <EmojiEventsIcon />
      </IconButton>

      <Popover
        id={id}
        open={open}
        anchorEl={anchorEl}
        onClose={handleClose}
        anchorOrigin={{ vertical: "bottom", horizontal: "right" }}
        transformOrigin={{ vertical: "top", horizontal: "right" }}
        PaperProps={{
          sx: {
            p: 2,
            minWidth: 220,
            backgroundColor: "#fefefe",
            boxShadow: 3,
            borderRadius: 2
          }
        }}
      >
        <Typography variant="h6" gutterBottom color="primary">
          🏆 Hi-Scores
        </Typography>

        <Divider sx={{ mb: 1 }} />

        <Stack spacing={1}>
          {sortedScores.length === 0 && (
            <Typography variant="body2" color="text.secondary">
              Aucun score enregistré.
            </Typography>
          )}

          {sortedScores.map(([gameID, { score }], idx) => (
            <Box key={gameID} sx={{ display: "flex", justifyContent: "space-between" }}>
              <Typography variant="body2" sx={{ color: "#333" }}>
                {gameID}
              </Typography>
              <Typography variant="body2" sx={{ fontWeight: "bold", color: "#009688" }}>
                {score}
              </Typography>
            </Box>
          ))}
        </Stack>
      </Popover>
    </>
  );
};

