const App = () => {
  const [selectedApp, setSelectedApp] = useState(null);
  
  const [mesAppIn, setmesAppIn] = useState(false);
useEffect(() => {
    document.title = "Mini Jeux de David Poilevey";
  }, []);


  const handleSelectApp = (app) => {
    
    setTimeout(() => { setSelectedApp(app); }, 500);
  };
  const handleToggleLeftPanel = () => {
   setSelectedApp(null)
  };

  // Crée un thème personnalisé avec les couleurs de casino
  const theme = createTheme({
    palette: {
      primary: {
        main: '#2690ceff', // Rouge foncé
      },
      secondary: {
        main: '#e78c1eff', // Saumon
      },
    },
  });
  const handleButtonKeyDown = (event) => {
    // Vérifiez si la touche tapée est la barre d'espace (code ASCII 32)
    if (event.keyCode === 32) {
      // Empêche le déclenchement du onClick
      event.preventDefault();
    }
  };
  return (
    <ThemeProvider theme={theme}>
      <div className="app-container">

        {/* Button to toggle the center panel */}
  
        <Box className="toggle-button">

          <IconButton className="tab-button" onClick={handleToggleLeftPanel} onKeyDown={handleButtonKeyDown}>
            <MenuOpen className="tab-button" />

          </IconButton>
        </Box>

        {/* Center panel */}
        <div className="center-panel">
          <Regles regle={selectedApp?.regle} />

   
          {/* <JeuxGrid allJeux={apps.flatMap(g => g.children)} onSelectApp={(app) => {
            const appToSelect = getAppByName(app.name)
            handleSelectApp(appToSelect)
          } }/> */}
           <AppPanel selectedApp={selectedApp}  handleSelectApp={(app)=>{
            handleSelectApp(app)}}/>
        </div>
      </div>
    </ThemeProvider>
  );
};

