import React, { createContext, useCallback, useContext, useEffect, useMemo, useState } from "react";
import { initialDistricts, NULL_GANGACTION, RESIDENT_TYPES } from "./GangData";
import { aiChooseAction, changeRelation, getBonusRelationnel, updateRelationsAndDefcon } from "./GangUtils";
import useShowAlert from "../jds/components/Message";

const GangCityContext = createContext(undefined);

export const useGangCity = () => {
  const context = useContext(GangCityContext);
  if (!context) {
    throw new Error("useGangCity doit être utilisé dans un GangCityProvider");
  }
  return context;
};


export function GangCityProvider({ children }) {
  const [districts, setDistricts] = useState(initialDistricts);
  const [events, setEvents] = useState([]);
  const [cityMood, setCityMood] = useState("neutre");
  const [playerDistrictId, setPlayerDistrictId] = useState(null);
    const { showAlert, SnackbarComponent } = useShowAlert();
    const [currentTurnIndex, setCurrentTurnIndex] = useState(0);
    const isPlayerTurn = districts[currentTurnIndex].id === playerDistrictId;
 
// Fonction pour gérer le tour d'un quartier (IA ou humain)
const nextTurn = () => {
  
  setCurrentTurnIndex(oldidx=> ((oldidx + 1) % districts.length));
}
useEffect(()=>{
// Si c'est une IA, elle joue automatiquement puis passe la main
  if (!isPlayerTurn) {
    setTimeout(() => {
      playAiTurn(districts[currentTurnIndex]);
      nextTurn();
    }, 800); // délai pour l'effet, optionnel
  }
},[currentTurnIndex]);

const deliverAnecdote=useCallback(()=> {
    const districtsWithAnecdotes = districts.filter(d => d.anecdotes && d.anecdotes.length > 0);
    if (districtsWithAnecdotes.length === 0) return null;

    // Choisir un district au hasard

    const district = districtsWithAnecdotes[Math.floor(Math.random() * districtsWithAnecdotes.length)];
    // Choisir une anecdote au hasard
    const anecdote = district.anecdotes[Math.floor(Math.random() * district.anecdotes.length)];

    // Ajouter l'anecdote au feed narratif
    setEvents(prevEvents => [
      ...prevEvents,
      {
        id: `${district.id}-anecdote-${Date.now()}`,
        author: district.name,
        content: anecdote,
        district: district.id,
        type: "anecdote",
        timestamp: new Date()
      }
    ]);
    
},[districts]);

 const endPlayerTurn = useCallback(() => {
   setDistricts(prevDistricts => {
      return prevDistricts.map(dist => {
        if (dist.id === playerDistrictId) {
          return {...dist, actionPoint:5};
        }
        return dist;
      })
    });
  nextTurn();
  if(Math.random()<0.1)
     deliverAnecdote();
},[nextTurn, deliverAnecdote]);

const playAiTurn = (district) => {
  // Choisir et exécuter une ou plusieurs actions IA ici
  let newDistrict = {...district};
  let paRestants = newDistrict.actionPoint;
  let actionChoisie = NULL_GANGACTION;
   const others = districts.filter(d=>d.id!==playerDistrictId);
  const districtLog=[];
  //choisis des actions a executer
  while(actionChoisie!=null && paRestants>0){
    actionChoisie = aiChooseAction(newDistrict, paRestants);
    if(actionChoisie!=null){
      const otherDistrict = actionChoisie.needOther?others[Math.floor(Math.random() * others.length)]:null;
      paRestants-=actionChoisie.cost;
      districtLog.push(actionChoisie.effect(newDistrict,otherDistrict, utilFunc));
    }
  }
  newDistrict = appliqueJournee(newDistrict);
  // save setDitricts
  setDistricts(prevDistricts=>{
    return prevDistricts.map(dist=>{
      if(dist.id===newDistrict.id){
        return newDistrict;
      }
      else {
        const other = others.find(o=>o.id===dist.id);
        if(other!=null)
          return other;        
      }
      return dist;
    })
  });
  
};
const appliqueJournee = (district)=>{

      // 1. Calcul des revenus totaux
      const totalRevenus = district.habitants
        ? district.habitants.reduce(
            (sum, h) => sum + h.proportion * (RESIDENT_TYPES.find(r=>r.id===h.archetype)?.revenus||0) * district.population,
            0
          )
        : 0;

      // 2. Mise à jour santé économique (exemple simple)
      let newSanteEco = district.santeEconomique + (totalRevenus / 100000) - 1; // ajuster les coefficients selon le jeu
    
      // 1.2 Relations évoluent (exemple aléatoire)
      const {defcon, newLinks} = updateRelationsAndDefcon(district,districts,events);// dernier arg : events TODO
          const bonusDeRelation = getBonusRelationnel(newLinks);
          newSanteEco += bonusDeRelation.santeEco;
      // 3. Evolution de l’humeur (exemple)
      let newMood = district.mood;
     // trouver comment calculer un bon mood

      // 4. Population évolue (exemple)
      let popDelta = Math.round((newSanteEco / 100) * 5); // la santé éco attire ou fait fuir
      popDelta+=bonusDeRelation.population;
      let newPopulation = Math.max(100, district.population + popDelta);

      // 5. Reputation évolue légèrement
      let newReputation = district.reputation + bonusDeRelation.reputation;

      // ... (logique à ajouter)
      return {
        ...district,
        defcon,
        santeEconomique: Math.max(-100, Math.min(100, newSanteEco)),
        mood: newMood,
        population: newPopulation,
        reputation: Math.max(-100, Math.min(100, newReputation)),
        links: newLinks
      }
    
}

const addLog = (message, options = {})=> {
  setEvents(prev => [
    ...prev,
    {
      id: `log-${Date.now()}-${Math.random()}`,
      author: options.author || "Ville",
      content: message,
      district: options.district?.id??options.district??playerDistrictId,
      type: options.type || "log",
      timestamp: new Date()
    }
  ]);
}
const city = useMemo(()=>{
  return {cityMood, districts}
},[cityMood, districts]);




const utilFunc = {
    city:city,
    changeRelation:changeRelation,
    addLog, showAlert
  };

  const value = {
    districts,
    setDistricts,
    events,
    setEvents,
    endPlayerTurn,
     playerDistrictId,
  setPlayerDistrictId,
     city, currentTurnIndex,
    utilFunc:utilFunc
    // Ajoute ici tes fonctions métier
  };
  return (
    <GangCityContext.Provider value={value}>
      {children}
       {SnackbarComponent}
    </GangCityContext.Provider>
  );
}
